function coeff = initilize_hb_coeff(cin,l_NONZERO)
    coder.inline("never");
    gain = 2;
    coeff = coder.nullcopy(zeros(2,33));
    
    for i = 1:(l_NONZERO-1)
        coeff(i) = gain * cin(2*i-1);
    end
    
    i = l_NONZERO;
    coeff(i) = gain * cin(2*(i-1));
end


function coeff = initilize_srrc_coeff(cin,l_NONZERO,ODD)
    coder.inline("never");
    gain = 2;
    coeff = coder.nullcopy(zeros(2,33));
    
    max = floor(l_NONZERO - ODD);
    j=1;
    for i = 1: max
        for k = 1:2
            coeff(k,i) = gain * cin(j);
            j = j+1;
        end
        % number of taps is one greater for odd phase filter
        if ODD
            k = 1;
            i = l_NONZERO; 
            coeff(k,i) = gain * cin((2 * i)-1);
        end
    end
end

function [cout,sout] = dds_compute(incr,N,cos_lut,fine_lut)
    coder.inline("never");
    cout    = coder.nullcopy(zeros(1,3200));
    sout    = coder.nullcopy(zeros(1,3200));
    persistent acc;
    if isempty(acc)
        acc = fi(0,1,33,31, 'RoundingMethod', 'floor', 'OverflowAction', 'Wrap');
    end 

    for i = 1:N
        %coder.hdl.literaltext("#pragma HLS pipeline II = 1 rewind");   
        acc(:) = incr + acc; 
        full_adr = bitsliceget(acc,32,21);
        msb = bitsliceget(full_adr,12,11);
        lsb = bitsliceget(full_adr,10,1);

        offset = fi(1025,0,11,0, 'RoundingMethod', 'floor', 'OverflowAction', 'Wrap');
        if msb  ==  0
            cos_adr      = lsb+1;
            cos_lut_word = cos_lut(cos_adr);
            if lsb==0 
                sin_lut_word = 0;
            else  
                sin_adr      = offset - lsb; 
                sin_lut_word =  cos_lut(sin_adr);
            end

        elseif msb  ==  1
            if lsb==0
                cos_lut_word = 0;
            else  
                cos_adr      = offset - lsb;
                cos_lut_word = -cos_lut(cos_adr);
            end
            sin_adr      = lsb+1;
            sin_lut_word = cos_lut(sin_adr);

        elseif msb  ==  3
            if lsb==0 
                cos_lut_word = 0;
            else  
                cos_adr      = offset - lsb;
                cos_lut_word =  cos_lut(cos_adr);
            end        
            sin_adr      =  lsb+1;
            sin_lut_word = -cos_lut(sin_adr);

        else          
            cos_adr      =  lsb+1;
            cos_lut_word = -cos_lut(cos_adr);
            if lsb==0 
                sin_lut_word = 0;
            else 
                sin_adr      = offset - lsb; 
                sin_lut_word = -cos_lut(sin_adr);
            end

        end
        fine_adr = bitsliceget(acc,20,12);
        fine_word = fine_lut(fine_adr+1);

        cout(i) = cos_lut_word - sin_lut_word * fine_word;
        sout(i) = sin_lut_word + cos_lut_word * fine_word;
    end 
end

function srcc_dout = fir_compute_i(din,srcc_coeff,srrc_l_INPUT, srrc_L_SUB,srrc_l_TDL,srrc_l_NONZERO,srrc_ODD)
    coder.inline("never");
    persistent sr;
    if isempty(sr)
         sr = zeros(1,63);
    end
    % Modification #1: Initialize srcc_dout as an array
    srcc_dout = coder.nullcopy(zeros(1,400));
    for p = 1:200
        coder.hdl.literaltext("#pragma HLS pipeline II = 16 rewind");       
        acc0    = 0;
        acc1    = 0;
        for i = 1:16
            even_index = int16(srrc_l_TDL - i +1);
            preadd_even = sr(i) + sr(even_index);
            prod_even = preadd_even * srcc_coeff(1,i);
            acc0 = prod_even + acc0;

            odd_index = int16(srrc_l_TDL - srrc_ODD - i+1);
            preadd_odd = sr(i) + sr(odd_index);
            prod_odd = preadd_odd * srcc_coeff(2,i);
            acc1 = prod_odd + acc1;
        end

        % center tap
        preadd_center = sr(srrc_l_NONZERO) + 0;
        prod_center = preadd_center * srcc_coeff(1,srrc_l_NONZERO);
        acc0 = prod_center + acc0; 

        for j = 33:-1:1
            if j == 1
               sr(1) = din(p);
            else 
                sr(j) = sr(j-1);
            end 
        end
        srcc_dout(2*p-1) = acc0;
        srcc_dout(2*p) = acc1;
    end
end

function srcc_dout = fir_compute_q(din,srcc_coeff,srrc_l_INPUT, srrc_L_SUB,srrc_l_TDL,srrc_l_NONZERO,srrc_ODD)
    coder.inline("never");
    persistent sr;
    if isempty(sr)
         sr = zeros(1,63);
    end
    % Modification #1: Initialize srcc_dout as an array
    srcc_dout = coder.nullcopy(zeros(1,400));
    for p = 1:srrc_l_INPUT
        acc0    = 0;
        acc1    = 0;
        coder.hdl.literaltext("#pragma HLS pipeline II = 16 rewind");       
        for i = 1:srrc_l_NONZERO - srrc_ODD
            preadd_even = sr(i) + sr(srrc_l_TDL - i +1);
            prod_even = preadd_even * srcc_coeff(1,i);
            acc0 = prod_even + acc0;
            preadd_odd = sr(i) + sr(srrc_l_TDL - srrc_ODD - i+1);
            prod_odd = preadd_odd * srcc_coeff(2,i);
            acc1 = prod_odd + acc1;
        end
            % center tap
            preadd_center = sr(srrc_l_NONZERO) + 0;
            prod_center = preadd_center * srcc_coeff(1,srrc_l_NONZERO);
            acc0 = prod_center + acc0;        
        for j = srrc_l_TDL:-1:2
            sr(j) = sr(j-1);
        end
        sr(1) = din(p);    
        srcc_dout(2*p-1) = acc0;
        srcc_dout(2*p) = acc1;
    end
end

function hb_dout = hb1_fir_i(l_TDL,hb1_l_NONZERO,din,Lhb1_WHOLE,l_INPUT,hb_coeff)
    coder.inline("never");
    persistent sr;
    if isempty(sr)
       sr  = zeros(1,63);
    end

    hb_dout = coder.nullcopy(zeros(1,800));
    for p = 1:l_INPUT
        coder.hdl.literaltext("#pragma HLS pipeline II = 8 rewind");       
        acc    = 0;
        for i = 1: hb1_l_NONZERO-1
            preadd = sr(i) + sr(l_TDL-i +1);
            prod = preadd * hb_coeff(i);
            acc = prod + acc;
        end 
        hb_dout(2*p-1) = acc;
        for j = l_TDL:-1:2
            sr(j) = sr(j-1);
        end
        sr(1) = din(p);
        hb_dout(2*p) = hb_coeff(hb1_l_NONZERO)*sr(hb1_l_NONZERO);     
    end
end

