function dout = duc_mix(dds_cos,dds_sin,dout_i,dout_q)
    coder.inline("never");
    persistent L_OUTPUT;
    persistent dout_tmp;
        dout    = coder.nullcopy(zeros(1,3200));
    if isempty(L_OUTPUT)
        L_OUTPUT = 16*200;
        dout_tmp = 0;
    end 
    
    for i = 1:L_OUTPUT 
        coder.hdl.literaltext("#pragma HLS pipeline II = 1 rewind"); 
        dout(i)  = dout_tmp;
        dout_tmp = dout_i(i) * dds_cos(i) -  dout_q(i) * dds_sin(i);  
    end
end